"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { Textarea } from "@/components/ui/textarea"
import { Checkbox } from "@/components/ui/checkbox"

/* ------------------------------------------------------------------ */
/* TextareaField                                                         */
/* ------------------------------------------------------------------ */

type TextareaFieldProps = React.ComponentProps<typeof Textarea> & {
  label?: React.ReactNode
  helper?: React.ReactNode
  error?: React.ReactNode
  optional?: boolean
  wrapperClassName?: string
}

function TextareaField({ label, helper, error, optional, id: idProp, wrapperClassName, ...props }: TextareaFieldProps) {
  const autoId = React.useId()
  const id = idProp ?? autoId
  return (
    <div data-slot="textarea-field" className={cn("flex flex-col gap-1.5", wrapperClassName)}>
      {label && (
        <label htmlFor={id} className="text-sm font-medium text-foreground">
          {label}
          {optional && <span className="ml-1 font-normal text-text-tertiary">(optional)</span>}
        </label>
      )}
      <Textarea
        id={id}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-error` : helper ? `${id}-helper` : undefined}
        {...props}
      />
      {error ? (
        <p id={`${id}-error`} className="text-xs text-text-error">{error}</p>
      ) : (
        helper && <p id={`${id}-helper`} className="text-xs text-text-tertiary">{helper}</p>
      )}
    </div>
  )
}

/* ------------------------------------------------------------------ */
/* CheckboxField — checkbox + label (+ description)                      */
/* Figma: ❖ Selectors / Checkbox Item (113:7985)                       */
/* ------------------------------------------------------------------ */

type CheckboxFieldProps = React.ComponentProps<typeof Checkbox> & {
  label: React.ReactNode
  description?: React.ReactNode
  wrapperClassName?: string
}

function CheckboxField({ label, description, id: idProp, wrapperClassName, className, ...props }: CheckboxFieldProps) {
  const autoId = React.useId()
  const id = idProp ?? autoId
  return (
    <label htmlFor={id} data-slot="checkbox-field" className={cn("flex cursor-pointer items-start gap-2", wrapperClassName)}>
      <Checkbox id={id} className={cn("mt-0.5", className)} {...props} />
      <span className="flex flex-col gap-0.5">
        <span className="text-sm text-text-secondary [&_a]:font-medium [&_a]:text-text-link [&_a]:hover:underline">{label}</span>
        {description && <span className="text-xs text-text-tertiary">{description}</span>}
      </span>
    </label>
  )
}

/* ------------------------------------------------------------------ */
/* FormActions — right-aligned button row used at the end of forms       */
/* ------------------------------------------------------------------ */

function FormActions({ children, align = "end", className }: { children: React.ReactNode; align?: "start" | "end" | "between"; className?: string }) {
  return (
    <div
      data-slot="form-actions"
      className={cn(
        "flex flex-wrap items-center gap-3",
        align === "end" && "justify-end",
        align === "between" && "justify-between",
        className
      )}
    >
      {children}
    </div>
  )
}

export { TextareaField, CheckboxField, FormActions }
export type { TextareaFieldProps, CheckboxFieldProps }

"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { cn } from "@/lib/utils"
import { CheckIcon, MinusIcon } from "lucide-react"
import * as React from "react"

/**
 * Base UI renders a hidden native <input> next to the visible control and gives it no name.
 * It is aria-hidden, but page checkers still list it as an unlabelled form control, so the
 * control's aria-label / aria-labelledby is mirrored onto it.
 */
function useNamedHiddenInput(inputRef: React.Ref<HTMLInputElement> | undefined, label?: string, labelledBy?: string) {
  return React.useCallback(
    (node: HTMLInputElement | null) => {
      if (node) {
        if (label) node.setAttribute("aria-label", label)
        else node.removeAttribute("aria-label")
        if (labelledBy) node.setAttribute("aria-labelledby", labelledBy)
        else node.removeAttribute("aria-labelledby")
      }
      if (typeof inputRef === "function") inputRef(node)
      else if (inputRef) (inputRef as React.RefObject<HTMLInputElement | null>).current = node
    },
    [inputRef, label, labelledBy]
  )
}

function Checkbox({ className, inputRef, ...props }: CheckboxPrimitive.Root.Props) {
  const namedInputRef = useNamedHiddenInput(inputRef, props["aria-label"], props["aria-labelledby"])
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      inputRef={namedInputRef}
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-border-control transition-colors duration-fast ease-entrance hover:not-data-checked:border-primary outline-none group-has-disabled/field:opacity-50 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:not-data-checked:border-border-control after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-primary focus-visible:ring-2 focus-visible:ring-ring/30 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 aria-invalid:aria-checked:border-primary dark:bg-muted/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground group-has-[:focus-visible]/field-label:data-checked:border-primary dark:data-checked:bg-primary data-indeterminate:border-primary data-indeterminate:bg-primary data-indeterminate:text-primary-foreground",
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        keepMounted
        data-slot="checkbox-indicator"
        className={cn(
          "grid place-content-center text-current opacity-0 transition-opacity ease-entrance duration-fast data-checked:opacity-100 data-indeterminate:opacity-100 [&>svg]:size-3.5 [&>svg:last-child]:hidden data-indeterminate:[&>svg:first-child]:hidden data-indeterminate:[&>svg:last-child]:block",
          // The box fills instantly (see Root's data-checked:bg-primary above);
          // the check stroke draws in after via stroke-dashoffset. 23 is
          // lucide's CheckIcon path length (getTotalLength()), rounded up by 1
          // so the draw never over/under-shoots. Uncheck reverses fast with no
          // draw — transitioning offset (not toggling display) is what lets a
          // mid-draw uncheck reverse cleanly instead of jumping. The offset is
          // negative because lucide's path starts at the top-right end: the
          // tick draws from its short stroke up to the long one, like by hand.
          "[&_svg_path]:[stroke-dasharray:23] [&_svg_path]:[stroke-dashoffset:-23] [&_svg_path]:transition-[stroke-dashoffset] [&_svg_path]:duration-fast [&_svg_path]:ease-entrance data-checked:[&_svg_path]:[stroke-dashoffset:0] data-checked:[&_svg_path]:duration-slow"
        )}
      >
        <CheckIcon />
        <MinusIcon />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const textareaVariants = cva(
  "w-full min-w-0 resize-y rounded-md border border-input bg-card px-3 py-2.5 text-sm transition-colors duration-fast ease-entrance outline-none placeholder:text-muted-foreground focus-visible:border-ring disabled:pointer-events-none disabled:cursor-not-allowed disabled:bg-muted/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 aria-invalid:focus-visible:ring-destructive dark:disabled:bg-muted/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
  {
    variants: {
      size: {
        // Density tokens (styles.css): compact 72/96/128, comfortable 80/112/144.
        sm: "min-h-(--textarea-sm)",
        default: "min-h-(--textarea-md)",
        lg: "min-h-(--textarea-lg) text-base",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
)

function Textarea({
  className,
  size = "default",
  showCount,
  maxLength,
  value,
  defaultValue,
  onChange,
  ...props
}: Omit<React.ComponentProps<"textarea">, "size"> &
  VariantProps<typeof textareaVariants> & {
    /** Show a "n/maxLength" character counter in the bottom-right corner. Requires maxLength. */
    showCount?: boolean
  }) {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue ?? "")
  const isControlled = value !== undefined
  const length = (isControlled ? value : uncontrolledValue)?.toString().length ?? 0
  const withCounter = showCount && maxLength !== undefined

  return (
    <div className="relative">
      <textarea
        data-slot="textarea"
        className={cn(textareaVariants({ size }), withCounter && "pb-6", className)}
        maxLength={maxLength}
        value={value}
        defaultValue={defaultValue}
        onChange={(event) => {
          if (!isControlled) setUncontrolledValue(event.target.value)
          onChange?.(event)
        }}
        {...props}
      />
      {withCounter && (
        <span className="pointer-events-none absolute right-3 bottom-2 text-xs text-text-tertiary tabular-nums">
          {length}/{maxLength}
        </span>
      )}
    </div>
  )
}

export { Textarea, textareaVariants }
